int str_iterator__iternext(py_Ref self) {
    int* ud = py_touserdata(self);
    int size;
    const char* data = py_tostrn(py_getslot(self, 0), &size);
    if(*ud == size) {
        py_newnil(py_retval());
        return 0;
    }
    int start = *ud;
    int len = c11__u8_header(data[*ud], false);
    *ud += len;
    py_newstrv(py_retval(), (c11_sv){data + start, len});
    return 1;
}

