    c11_color32 color;
    color.r = (unsigned char)(v.x * 255);
    color.g = (unsigned char)(v.y * 255);
    color.b = (unsigned char)(v.z * 255);
    color.a = 255;
    py_newcolor32(py_retval(), color);
