void* py_malloc(size_t size) { return pk_app_callbacks.malloc(size); }

void* py_realloc(void* ptr, size_t size) { return pk_app_callbacks.realloc(ptr, size); }

void py_free(void* ptr) { pk_app_callbacks.free(ptr); }

